import{_ as i,o as a,c as o,ag as s}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Agent Bridge","description":"","frontmatter":{},"headers":[],"relativePath":"features/agent-bridge.md","filePath":"features/agent-bridge.md"}'),r={name:"features/agent-bridge.md"};function t(d,e,l,n,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-bridge" tabindex="-1">Agent Bridge <a class="header-anchor" href="#agent-bridge" aria-label="Permalink to &quot;Agent Bridge&quot;">​</a></h1><p>Agent Bridge discovers and manages local agent CLIs running inside tmux. It supports mixed Claude Code and Codex CLI sessions in the same view.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The bridge performs a provider-aware tmux discovery pass and classifies each matching pane as <code>claude-code</code> or <code>codex-cli</code>. The UI can show all sessions together or filter to one provider.</p><p>Session cards include:</p><ul><li>Provider badge</li><li>tmux target</li><li>Current working directory</li><li>Live preview</li><li>Attach, fullscreen, and kill controls</li></ul><p>The terminal grid is shared across providers. Read-only and interactive modes work the same way whether the pane is Claude Code or Codex.</p><p>Provider filters are explicit:</p><ul><li><strong>All</strong> — mixed Claude Code and Codex sessions</li><li><strong>Claude Code</strong> — Claude Code panes only</li><li><strong>Codex</strong> — Codex panes only</li></ul><h2 id="new-sessions" tabindex="-1">New Sessions <a class="header-anchor" href="#new-sessions" aria-label="Permalink to &quot;New Sessions&quot;">​</a></h2><p>The new session dialog starts with a provider choice.</p><p>Claude Code keeps the existing session modes:</p><ul><li>Plain session</li><li>Worktree session</li><li>Resume session</li></ul><p>Codex CLI supports:</p><ul><li>New session with <code>codex --cd &lt;directory&gt;</code></li><li>Resume by session id or <code>--last</code></li><li>Fork by session id or <code>--last</code></li><li>Model and profile selectors with custom-value fallback</li><li>Optional sandbox, approval policy, web search, and prompt seed</li></ul><p>Dangerous Codex bypass mode is exposed as an explicit advanced option because it disables approval and sandbox protections.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>The frontend route <code>/agent-bridge</code> is the primary route. <code>/cc-bridge</code> remains as a compatibility alias.</p><p>The backend keeps <code>/api/v1/cc-bridge/*</code> for existing callers and adds <code>/api/v1/agent-bridge/*</code> for provider-aware clients.</p><h2 id="smoke-coverage" tabindex="-1">Smoke Coverage <a class="header-anchor" href="#smoke-coverage" aria-label="Permalink to &quot;Smoke Coverage&quot;">​</a></h2><p>Multi-provider smoke checks should cover mixed discovery, provider filters, attach/read-only/interactive terminal behavior, Codex spawn/resume/fork options, and the legacy <code>/cc-bridge</code> compatibility route. Claude-only transcript, usage, context, plugin, permission, hook, agent, skill, and memory pages should stay hidden or disabled when Codex is the selected provider until provider-aware equivalents exist.</p>',21)])])}const g=i(r,[["render",t]]);export{u as __pageData,g as default};
